const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeWinnipeg = ee.Geometry.Polygon([
    [[-98.5, 53.5], [-96.0, 53.5], [-96.0, 50.0], [-98.5, 50.0], [-98.5, 53.5]]
  ]);

  const date1_start = '2021-05-05';
  const date1_end = '2021-05-09';
  const date2_start = '2021-05-17';
  const date2_end = '2021-05-21';

  // 2. Data Acquisition
  const s2_col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(lakeWinnipeg)
    .filterDate(date1_start, date1_end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  const s2_col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(lakeWinnipeg)
    .filterDate(date2_start, date2_end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  // Check collection sizes
  const size1 = s2_col1.size().getInfo();
  const size2 = s2_col2.size().getInfo();

  console.log(`May 7 period images: ${size1}`);
  console.log(`May 19 period images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get least cloudy images
  const img1 = s2_col1.sort('CLOUDY_PIXEL_PERCENTAGE').first();
  const img2 = s2_col2.sort('CLOUDY_PIXEL_PERCENTAGE').first();

  // 3. Ice detection function - high reflectance in blue/green bands indicates ice
  function detectIce(img) {
    // Cloud mask using QA60 band
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const qa = img.select('QA60');
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));

    // Apply cloud mask
    const masked = img.updateMask(mask);

    // Ice detection: high reflectance in blue band (B2) and green band (B3)
    const blue = masked.select('B2');
    const green = masked.select('B3');

    // Simple threshold: pixels with high reflectance in both bands likely ice
    const ice = blue.gt(1500).and(green.gt(1500));

    return ice.rename('ice');
  }

  // Apply ice detection
  const ice1 = detectIce(img1);
  const ice2 = detectIce(img2);

  // 4. Calculate ice extent (pixel counts)
  const iceStats1 = ice1.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeWinnipeg,
    scale: 100,
    maxPixels: 1e9
  });

  const iceStats2 = ice2.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeWinnipeg,
    scale: 100,
    maxPixels: 1e9
  });

  const iceCount1 = iceStats1.get('ice').getInfo();
  const iceCount2 = iceStats2.get('ice').getInfo();

  console.log(`May 7 ice pixels: ${iceCount1}`);
  console.log(`May 19 ice pixels: ${iceCount2}`);

  // Check for valid pixels
  if (iceCount1 === null || iceCount2 === null || iceCount1 === 0 || iceCount2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Validation & Final Answer
  const decrease = iceCount2 < iceCount1;
  const changePercent = ((iceCount2 - iceCount1) / iceCount1 * 100).toFixed(1);

  console.log(`Ice change: ${changePercent}%`);

  if (decrease) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
